import React, { useState, useEffect, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../../context/AuthContext";
import api from "../../utils/api";
import Navbar from "../../components/layout/Navbar";
import "./Admin.css";

export default function AdminPanel() {
  const { user } = useAuth();
  const navigate  = useNavigate();
  const [tab,     setTab]     = useState("dashboard");
  const [stats,   setStats]   = useState(null);
  const [users,   setUsers]   = useState([]);
  const [flaggedPosts,    setFlaggedPosts]    = useState([]);
  const [reportedPosts,   setReportedPosts]   = useState([]);
  const [flaggedComments, setFlaggedComments] = useState([]);
  const [allPosts,        setAllPosts]        = useState([]);
  const [search,  setSearch]  = useState("");
  const [loading, setLoading] = useState(false);
  const [toast,   setToast]   = useState("");

  useEffect(() => {
    if (!user || user.role !== "admin") { navigate("/"); return; }
    fetchStats();
  }, [user]);

  const showToast = (msg) => { setToast(msg); setTimeout(() => setToast(""), 3000); };

  const fetchStats = async () => {
    try { const r = await api.get("/admin/stats"); setStats(r.data); } catch {}
  };

  const fetchUsers = useCallback(async () => {
    setLoading(true);
    try { const r = await api.get(`/admin/users?search=${search}`); setUsers(r.data.users); }
    catch {} finally { setLoading(false); }
  }, [search]);

  const fetchFlaggedPosts    = async () => { try { const r = await api.get("/admin/flagged-posts");   setFlaggedPosts(r.data.posts); } catch {} };
  const fetchReportedPosts   = async () => { try { const r = await api.get("/admin/reported-posts");  setReportedPosts(r.data.posts); } catch {} };
  const fetchFlaggedComments = async () => { try { const r = await api.get("/admin/flagged-comments"); setFlaggedComments(r.data.comments); } catch {} };
  const fetchAllPosts        = async () => { try { const r = await api.get("/admin/posts");            setAllPosts(r.data.posts); } catch {} };

  useEffect(() => {
    if (tab === "users")            fetchUsers();
    if (tab === "flagged-posts")    fetchFlaggedPosts();
    if (tab === "reported-posts")   fetchReportedPosts();
    if (tab === "flagged-comments") fetchFlaggedComments();
    if (tab === "all-posts")        fetchAllPosts();
  }, [tab]);

  const banUser = async (id, username) => {
    const reason = prompt(`Ban reason for @${username}:`, "Violated community guidelines");
    if (!reason) return;
    try {
      await api.put(`/admin/users/${id}/ban`, { reason });
      showToast(`✅ @${username} banned`);
      fetchUsers();
      fetchStats();
    } catch (e) { showToast("❌ " + (e.response?.data?.message || "Error")); }
  };

  const unbanUser = async (id, username) => {
    try {
      await api.put(`/admin/users/${id}/unban`);
      showToast(`✅ @${username} unbanned`);
      fetchUsers();
      fetchStats();
    } catch (e) { showToast("❌ Error"); }
  };

  const removePost = async (id, which) => {

    try {
      await api.put(`/admin/posts/${id}/remove`);
      showToast("✅ Post removed");
      if (which === "flagged")   fetchFlaggedPosts();
      if (which === "reported")  fetchReportedPosts();
      if (which === "all")       fetchAllPosts();
      fetchStats();
    } catch {}
  };

  const approvePost = async (id, which) => {
    try {
      await api.put(`/admin/posts/${id}/approve`);
      showToast("✅ Post approved & flag cleared");
      if (which === "flagged")  fetchFlaggedPosts();
      if (which === "reported") fetchReportedPosts();
      fetchStats();
    } catch {}
  };

  const removeComment = async (id) => {

    try {
      await api.put(`/admin/comments/${id}/remove`);
      showToast("✅ Comment removed");
      fetchFlaggedComments();
      fetchStats();
    } catch {}
  };

  const timeAgo = (d) => {
    const s = Math.floor((Date.now() - new Date(d)) / 1000);
    if (s < 60) return `${s}s ago`;
    if (s < 3600) return `${Math.floor(s/60)}m ago`;
    if (s < 86400) return `${Math.floor(s/3600)}h ago`;
    return `${Math.floor(s/86400)}d ago`;
  };

  if (!user || user.role !== "admin") return null;

  return (
    <>
      <Navbar />
      {toast && <div className="admin-toast">{toast}</div>}
      <div className="admin-wrap">

        {/* SIDEBAR */}
        <aside className="admin-sidebar">
          <div className="admin-brand">🛡️ Admin Panel</div>
          {[
            { id: "dashboard",        icon: "📊", label: "Dashboard" },
            { id: "users",            icon: "👥", label: "Users" },
            { id: "flagged-posts",    icon: "🚩", label: "Flagged Posts",    badge: stats?.flaggedPosts },
            { id: "reported-posts",   icon: "📋", label: "Reported Posts",   badge: stats?.reportedPosts },
            { id: "flagged-comments", icon: "💬", label: "Flagged Comments", badge: stats?.flaggedComments },
            { id: "all-posts",        icon: "📝", label: "All Posts" },
          ].map(({ id, icon, label, badge }) => (
            <div key={id} className={`admin-nav-item ${tab === id ? "active" : ""}`} onClick={() => setTab(id)}>
              <span>{icon} {label}</span>
              {badge > 0 && <span className="admin-badge">{badge}</span>}
            </div>
          ))}
          <div className="admin-nav-item" onClick={() => navigate("/")}>← Back to Echo</div>
        </aside>

        {/* MAIN */}
        <main className="admin-main">

          {/* DASHBOARD */}
          {tab === "dashboard" && (
            <div>
              <h1 className="admin-title">Dashboard</h1>
              <div className="stats-grid">
                {[
                  { label: "Total Users",       value: stats?.users,           color: "#3b82f6", icon: "👥" },
                  { label: "Total Posts",        value: stats?.posts,           color: "#10b981", icon: "📝" },
                  { label: "Comments",           value: stats?.comments,        color: "#8b5cf6", icon: "💬" },
                  { label: "Communities",        value: stats?.communities,     color: "#f59e0b", icon: "🏘️" },
                  { label: "Flagged Posts",      value: stats?.flaggedPosts,    color: "#ef4444", icon: "🚩" },
                  { label: "Reported Posts",     value: stats?.reportedPosts,   color: "#f97316", icon: "📋" },
                  { label: "Flagged Comments",   value: stats?.flaggedComments, color: "#ec4899", icon: "⚠️" },
                  { label: "Banned Users",       value: stats?.bannedUsers,     color: "#6b7280", icon: "🚫" },
                ].map(({ label, value, color, icon }) => (
                  <div key={label} className="stat-card" style={{ borderTop: `4px solid ${color}` }}>
                    <div className="stat-icon">{icon}</div>
                    <div className="stat-value" style={{ color }}>{value ?? "..."}</div>
                    <div className="stat-label">{label}</div>
                  </div>
                ))}
              </div>
              <div className="admin-card" style={{ marginTop: 20 }}>
                <h3 style={{ marginBottom: 12, color: "#111827" }}>Quick Actions</h3>
                <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
                  <button className="admin-btn blue"  onClick={() => setTab("flagged-posts")}>Review Flagged Posts ({stats?.flaggedPosts})</button>
                  <button className="admin-btn orange" onClick={() => setTab("reported-posts")}>Review Reports ({stats?.reportedPosts})</button>
                  <button className="admin-btn red"    onClick={() => setTab("flagged-comments")}>Flagged Comments ({stats?.flaggedComments})</button>
                  <button className="admin-btn gray"   onClick={() => setTab("users")}>Manage Users</button>
                </div>
              </div>
            </div>
          )}

          {/* USERS */}
          {tab === "users" && (
            <div>
              <h1 className="admin-title">Users</h1>
              <div style={{ display: "flex", gap: 10, marginBottom: 16 }}>
                <input className="admin-search" placeholder="Search by name, email or username..." value={search}
                  onChange={e => setSearch(e.target.value)} onKeyDown={e => e.key === "Enter" && fetchUsers()} />
                <button className="admin-btn blue" onClick={fetchUsers}>Search</button>
              </div>
              {loading ? <div className="admin-loading">Loading...</div> :
                <div className="admin-card">
                  <table className="admin-table">
                    <thead><tr><th>User</th><th>Email</th><th>Role</th><th>Verified</th><th>Warnings</th><th>Status</th><th>Joined</th><th>Actions</th></tr></thead>
                    <tbody>
                      {users.map(u => (
                        <tr key={u._id} className={u.isBanned ? "banned-row" : ""}>
                          <td><strong>@{u.username}</strong><br/><span style={{fontSize:11,color:"#6b7280"}}>{u.firstName} {u.lastName}</span></td>
                          <td style={{fontSize:12}}>{u.email}</td>
                          <td><span className={`role-badge ${u.role}`}>{u.role}</span></td>
                          <td>{u.isEmailVerified ? "✅" : "❌"}</td>
                          <td style={{textAlign:"center"}}>{u.warnings > 0 ? <span style={{color:"#ef4444",fontWeight:600}}>{u.warnings}</span> : 0}</td>
                          <td>{u.isBanned ? <span className="status-banned">Banned</span> : <span className="status-active">Active</span>}</td>
                          <td style={{fontSize:11,color:"#6b7280"}}>{timeAgo(u.createdAt)}</td>
                          <td>
                            <div style={{display:"flex",gap:4}}>
                              {u.isBanned
                                ? <button className="action-btn green" onClick={() => unbanUser(u._id, u.username)}>Unban</button>
                                : <button className="action-btn red"   onClick={() => banUser(u._id, u.username)}>Ban</button>
                              }
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  {users.length === 0 && <div className="admin-empty">No users found</div>}
                </div>
              }
            </div>
          )}

          {/* FLAGGED POSTS */}
          {tab === "flagged-posts" && (
            <div>
              <h1 className="admin-title">🚩 Flagged Posts</h1>
              {flaggedPosts.length === 0
                ? <div className="admin-empty-box">✅ No flagged posts!</div>
                : flaggedPosts.map(p => (
                  <div key={p._id} className="admin-card" style={{marginBottom:12,borderLeft:"4px solid #ef4444"}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}>
                      <div style={{flex:1}}>
                        <div style={{fontWeight:600,fontSize:15,color:"#111827",marginBottom:4}}>{p.title}</div>
                        <div style={{fontSize:12,color:"#6b7280",marginBottom:8}}>
                          by @{p.author?.username} in <strong>c/{p.community?.name}</strong> · {timeAgo(p.createdAt)}
                        </div>
                        <p style={{fontSize:13,color:"#374151",marginBottom:8,lineHeight:1.5}}>{p.content?.substring(0,200)}{p.content?.length > 200 ? "..." : ""}</p>
                        <div className="flag-reason">⚠️ {p.flagReason}</div>
                      </div>
                    </div>
                    <div style={{display:"flex",gap:8,marginTop:12}}>
                      <button className="admin-btn green" onClick={() => approvePost(p._id, "flagged")}>✅ Approve & Clear Flag</button>
                      <button className="admin-btn red"   onClick={() => removePost(p._id, "flagged")}>🗑️ Remove Post</button>
                    </div>
                  </div>
                ))
              }
            </div>
          )}

          {/* REPORTED POSTS */}
          {tab === "reported-posts" && (
            <div>
              <h1 className="admin-title">📋 Reported Posts</h1>
              {reportedPosts.length === 0
                ? <div className="admin-empty-box">✅ No reported posts!</div>
                : reportedPosts.map(p => (
                  <div key={p._id} className="admin-card" style={{marginBottom:12,borderLeft:"4px solid #f97316"}}>
                    <div style={{fontWeight:600,fontSize:15,color:"#111827",marginBottom:4}}>{p.title}</div>
                    <div style={{fontSize:12,color:"#6b7280",marginBottom:8}}>
                      by @{p.author?.username} in <strong>c/{p.community?.name}</strong> · {timeAgo(p.createdAt)}
                    </div>
                    <p style={{fontSize:13,color:"#374151",marginBottom:8}}>{p.content?.substring(0,200)}{p.content?.length > 200 ? "..." : ""}</p>
                    <div style={{marginBottom:10}}>
                      {p.reports?.map((r, i) => (
                        <span key={i} className="report-tag">🚩 {r.reason}</span>
                      ))}
                    </div>
                    <div style={{display:"flex",gap:8}}>
                      <button className="admin-btn green" onClick={() => approvePost(p._id, "reported")}>✅ Clear Reports</button>
                      <button className="admin-btn red"   onClick={() => removePost(p._id, "reported")}>🗑️ Remove Post</button>
                    </div>
                  </div>
                ))
              }
            </div>
          )}

          {/* FLAGGED COMMENTS */}
          {tab === "flagged-comments" && (
            <div>
              <h1 className="admin-title">💬 Flagged Comments</h1>
              {flaggedComments.length === 0
                ? <div className="admin-empty-box">✅ No flagged comments!</div>
                : flaggedComments.map(c => (
                  <div key={c._id} className="admin-card" style={{marginBottom:10,borderLeft:"4px solid #ec4899"}}>
                    <div style={{fontSize:12,color:"#6b7280",marginBottom:6}}>
                      by @{c.author?.username} on post: <strong>"{c.post?.title?.substring(0,50)}"</strong> · {timeAgo(c.createdAt)}
                    </div>
                    <div style={{background:"#fef2f2",border:"1px solid #fecaca",borderRadius:8,padding:"8px 12px",fontSize:13,color:"#7f1d1d",marginBottom:8}}>
                      "{c.content}"
                    </div>
                    <div className="flag-reason">⚠️ {c.flagReason}</div>
                    <button className="admin-btn red" style={{marginTop:8}} onClick={() => removeComment(c._id)}>🗑️ Remove Comment</button>
                  </div>
                ))
              }
            </div>
          )}

          {/* ALL POSTS */}
          {tab === "all-posts" && (
            <div>
              <h1 className="admin-title">📝 All Posts</h1>
              <div className="admin-card">
                <table className="admin-table">
                  <thead><tr><th>Title</th><th>Author</th><th>Community</th><th>Likes</th><th>Status</th><th>Date</th><th>Action</th></tr></thead>
                  <tbody>
                    {allPosts.map(p => (
                      <tr key={p._id}>
                        <td style={{maxWidth:200}}><div style={{fontSize:13,fontWeight:500,color:"#111827",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{p.title}</div></td>
                        <td style={{fontSize:12}}>@{p.author?.username}</td>
                        <td><span style={{background:p.community?.color+"20",color:p.community?.color,padding:"2px 8px",borderRadius:10,fontSize:11,fontWeight:500}}>c/{p.community?.name}</span></td>
                        <td style={{textAlign:"center"}}>❤️ {p.likes?.length || 0}</td>
                        <td>{p.isFlagged ? <span className="status-banned">Flagged</span> : <span className="status-active">OK</span>}</td>
                        <td style={{fontSize:11,color:"#6b7280"}}>{timeAgo(p.createdAt)}</td>
                        <td><button className="action-btn red" onClick={() => removePost(p._id, "all")}>Remove</button></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                {allPosts.length === 0 && <div className="admin-empty">No posts yet</div>}
              </div>
            </div>
          )}

        </main>
      </div>
    </>
  );
}
